window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7e0d1c312b22b1f6"]={"versions": [{"id": "FIG-7e0d1c312b22b1f6", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm der AUTOSAR BFX-Bibliothek (Bit Function Library). Es spezifiziert die Header- und Quelldatei-Abhängigkeiten sowie die Compiler-Inklusionshierarchie innerhalb des Moduls und zu externen Basiskomponenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Entitäten:</li>\n<li><code>Bfx_&lt;Name&gt;.c</code>: C-Quelldatei bzw. Quelldateien der BFX-Bibliotheksroutinen (parametrisiert nach Funktions-/Routinenname).</li>\n<li><code>Bfx.h</code>: Zentraler Modul-Header der BFX-Bibliothek mit Schnittstellendeklarationen.</li>\n<li><code>Std_Types.h</code>: AUTOSAR-Standardtypdefinitionen (externe Basisbibliothek).</li>\n<li><code>MemMap.h</code>: Header für das Memory-Mapping zur Zuordnung von Code- und Datensegmenten.</li>\n<li>Relationen (gerichtete Pfeile mit Stereotyp/Bezeichnung <code>includes</code>):</li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>Bfx.h</code></li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>MemMap.h</code></li>\n<li><code>Bfx.h</code> -> <code>Std_Types.h</code></li>\n<li><code>Bfx.h</code> -> <code>MemMap.h</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abhängigkeitsmodell zur Kompilierzeit (#include-Hierarchie):</p>\n<ol class=\"fig-list\">\n<li><code>Bfx_&lt;Name&gt;.c</code> inkludiert den Modul-Header <code>Bfx.h</code> zur Funktionsprototyp-Deklaration sowie <code>MemMap.h</code> zur Segmentierung des Quellcodes.</li>\n<li><code>Bfx.h</code> inkludiert <code>Std_Types.h</code> zur Bereitstellung der Standarddatentypen und <code>MemMap.h</code> für inline- oder makrobasierte Speicherdefinitionen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Inklusionsstruktur für Implementierer der AUTOSAR Bit Function Library:</li>\n<li>Jede Implementierungsdatei <code>Bfx_&lt;Name&gt;.c</code> muss <code>Bfx.h</code> und das Speicherkonzept via <code>MemMap.h</code> einbinden.</li>\n<li>Der öffentliche Modul-Header <code>Bfx.h</code> muss <code>Std_Types.h</code> sowie <code>MemMap.h</code> einbinden, um vollständige Typdefinitionen sicherzustellen.</li>\n<li>Zyklische Abhängigkeiten sind ausgeschlossen; die Inklusionsordnung ist unidirektional.</li>\n</ul>"}, {"id": "FIG-14fa21f9963622e5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm der AUTOSAR BFX-Bibliothek (Bit Function Library). Es spezifiziert die Header- und Quelldatei-Abhängigkeiten sowie die Compiler-Inklusionshierarchie innerhalb des Moduls und zu externen Basiskomponenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Entitäten:</li>\n<li><code>Bfx_&lt;Name&gt;.c</code>: C-Quelldatei bzw. Quelldateien der BFX-Bibliotheksroutinen (parametrisiert nach Funktions-/Routinenname).</li>\n<li><code>Bfx.h</code>: Zentraler Modul-Header der BFX-Bibliothek mit Schnittstellendeklarationen.</li>\n<li><code>Std_Types.h</code>: AUTOSAR-Standardtypdefinitionen (externe Basisbibliothek).</li>\n<li><code>Bfx_MemMap.h</code>: Modulspezifischer Header für das Memory-Mapping zur Zuordnung von Code- und Datensegmenten der BFX-Bibliothek.</li>\n<li>Relationen (gerichtete Pfeile mit Stereotyp/Bezeichnung <code>includes</code>):</li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>Bfx.h</code></li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>Bfx_MemMap.h</code></li>\n<li><code>Bfx.h</code> -> <code>Std_Types.h</code></li>\n<li><code>Bfx.h</code> -> <code>Bfx_MemMap.h</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abhängigkeitsmodell zur Kompilierzeit (#include-Hierarchie):</p>\n<ol class=\"fig-list\">\n<li><code>Bfx_&lt;Name&gt;.c</code> inkludiert den Modul-Header <code>Bfx.h</code> zur Funktionsprototyp-Deklaration sowie <code>Bfx_MemMap.h</code> zur Segmentierung des Quellcodes.</li>\n<li><code>Bfx.h</code> inkludiert <code>Std_Types.h</code> zur Bereitstellung der Standarddatentypen und <code>Bfx_MemMap.h</code> für speicherbezogene Deklarationen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Inklusionsstruktur für Implementierer der AUTOSAR Bit Function Library:</li>\n<li>Jede Implementierungsdatei <code>Bfx_&lt;Name&gt;.c</code> muss <code>Bfx.h</code> und das Speicherkonzept über die modulspezifische Datei <code>Bfx_MemMap.h</code> einbinden.</li>\n<li>Der Modul-Header <code>Bfx.h</code> muss <code>Std_Types.h</code> sowie <code>Bfx_MemMap.h</code> einbinden.</li>\n<li>Verwendung des modulspezifischen Memory-Mapping-Headers <code>Bfx_MemMap.h</code> anstelle einer generischen <code>MemMap.h</code>.</li>\n<li>Unidirektionale Inklusionshierarchie ohne zyklische Abhängigkeiten.</li>\n</ul>"}, {"id": "FIG-e875d5c396249dbf", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm der AUTOSAR BFX-Bibliothek (Bit Function Library). Es spezifiziert die Header- und Quelldatei-Abhängigkeiten sowie die Compiler-Inklusionshierarchie innerhalb des Moduls und zu externen Basiskomponenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Entitäten:</li>\n<li><code>Bfx_&lt;Name&gt;.c</code>: C-Quelldatei bzw. Quelldateien der BFX-Bibliotheksroutinen (parametrisiert nach Funktions-/Routinenname).</li>\n<li><code>Bfx.h</code>: Zentraler Modul-Header der BFX-Bibliothek mit Schnittstellendeklarationen.</li>\n<li><code>Std_Types.h</code>: AUTOSAR-Standardtypdefinitionen (externe Basisbibliothek).</li>\n<li><code>Bfx_MemMap.h</code>: Modulspezifischer Header für das Memory-Mapping zur Zuordnung von Code- und Datensegmenten der BFX-Bibliothek.</li>\n<li>Relationen (gerichtete Pfeile mit Stereotyp/Bezeichnung <code>includes</code>):</li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>Bfx.h</code></li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>Bfx_MemMap.h</code></li>\n<li><code>Bfx.h</code> -> <code>Std_Types.h</code></li>\n<li><code>Bfx.h</code> -> <code>Bfx_MemMap.h</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abhängigkeitsmodell zur Kompilierzeit (#include-Hierarchie):</p>\n<ol class=\"fig-list\">\n<li><code>Bfx_&lt;Name&gt;.c</code> inkludiert den Modul-Header <code>Bfx.h</code> zur Funktionsprototyp-Deklaration sowie <code>Bfx_MemMap.h</code> zur Segmentierung des Quellcodes.</li>\n<li><code>Bfx.h</code> inkludiert <code>Std_Types.h</code> zur Bereitstellung der Standarddatentypen und <code>Bfx_MemMap.h</code> für speicherbezogene Deklarationen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Inklusionsstruktur für Implementierer der AUTOSAR Bit Function Library:</li>\n<li>Jede Implementierungsdatei <code>Bfx_&lt;Name&gt;.c</code> muss <code>Bfx.h</code> und das Speicherkonzept über die modulspezifische Datei <code>Bfx_MemMap.h</code> einbinden.</li>\n<li>Der Modul-Header <code>Bfx.h</code> muss <code>Std_Types.h</code> sowie <code>Bfx_MemMap.h</code> einbinden.</li>\n<li>Verwendung des modulspezifischen Memory-Mapping-Headers <code>Bfx_MemMap.h</code> anstelle einer generischen <code>MemMap.h</code>.</li>\n<li>Unidirektionale Inklusionshierarchie ohne zyklische Abhängigkeiten.</li>\n</ul>"}, {"id": "FIG-96a85fbfa1cc2bf7", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Dateistruktur- und Inklusionsdiagramm der AUTOSAR BFX-Bibliothek (Bit Function Library). Es spezifiziert die Header- und Quelldatei-Abhängigkeiten sowie die Compiler-Inklusionshierarchie innerhalb des Moduls und zu externen Basiskomponenten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Entitäten:</li>\n<li><code>Bfx_&lt;Name&gt;.c</code>: C-Quelldatei bzw. Quelldateien der BFX-Bibliotheksroutinen (parametrisiert nach Funktions-/Routinenname).</li>\n<li><code>Bfx.h</code>: Zentraler Modul-Header der BFX-Bibliothek mit Schnittstellendeklarationen.</li>\n<li><code>Std_Types.h</code>: AUTOSAR-Standardtypdefinitionen (externe Basisbibliothek).</li>\n<li><code>Bfx_MemMap.h</code>: Modulspezifischer Header für das Memory-Mapping zur Zuordnung von Code- und Datensegmenten der BFX-Bibliothek.</li>\n<li>Relationen (gerichtete Pfeile mit Stereotyp/Bezeichnung <code>includes</code>):</li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>Bfx.h</code></li>\n<li><code>Bfx_&lt;Name&gt;.c</code> -> <code>Bfx_MemMap.h</code></li>\n<li><code>Bfx.h</code> -> <code>Std_Types.h</code></li>\n<li><code>Bfx.h</code> -> <code>Bfx_MemMap.h</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Abhängigkeitsmodell zur Kompilierzeit (#include-Hierarchie):</p>\n<ol class=\"fig-list\">\n<li><code>Bfx_&lt;Name&gt;.c</code> inkludiert den Modul-Header <code>Bfx.h</code> zur Funktionsprototyp-Deklaration sowie <code>Bfx_MemMap.h</code> zur Segmentierung des Quellcodes.</li>\n<li><code>Bfx.h</code> inkludiert <code>Std_Types.h</code> zur Bereitstellung der Standarddatentypen und <code>Bfx_MemMap.h</code> für speicherbezogene Deklarationen.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Inklusionsstruktur für Implementierer der AUTOSAR Bit Function Library:</li>\n<li>Jede Implementierungsdatei <code>Bfx_&lt;Name&gt;.c</code> muss <code>Bfx.h</code> und das Speicherkonzept über die modulspezifische Datei <code>Bfx_MemMap.h</code> einbinden.</li>\n<li>Der Modul-Header <code>Bfx.h</code> muss <code>Std_Types.h</code> sowie <code>Bfx_MemMap.h</code> einbinden.</li>\n<li>Verwendung des modulspezifischen Memory-Mapping-Headers <code>Bfx_MemMap.h</code> anstelle einer generischen <code>MemMap.h</code>.</li>\n<li>Unidirektionale Inklusionshierarchie ohne zyklische Abhängigkeiten.</li>\n</ul>"}], "trans": [{"from": "FIG-7e0d1c312b22b1f6", "to": "FIG-14fa21f9963622e5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Dateiname <code>MemMap.h</code> wurde zu modulspezifischem <code>Bfx_MemMap.h</code> präzisiert.</li>\n</ul>"}, {"from": "FIG-14fa21f9963622e5", "to": "FIG-e875d5c396249dbf", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e875d5c396249dbf", "to": "FIG-96a85fbfa1cc2bf7", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
